# Excel to CSV Converter using Qt5

Here's a complete C++ program using Qt5 that creates a GUI application to convert all Excel files in a selected directory to CSV files:

```cpp
#include <QApplication>
#include <QMainWindow>
#include <QPushButton>
#include <QFileDialog>
#include <QMessageBox>
#include <QVBoxLayout>
#include <QLabel>
#include <QDir>
#include <QProcess>
#include <QDebug>

class ExcelToCsvConverter : public QMainWindow {
    Q_OBJECT

public:
    ExcelToCsvConverter(QWidget *parent = nullptr) : QMainWindow(parent) {
        setupUI();
    }

private slots:
    void selectDirectory() {
        QString dir = QFileDialog::getExistingDirectory(this, "Select Directory Containing Excel Files",
                                                       QDir::homePath(),
                                                       QFileDialog::ShowDirsOnly | QFileDialog::DontResolveSymlinks);

        if (!dir.isEmpty()) {
            directoryLabel->setText("Selected Directory: " + dir);
            convertButton->setEnabled(true);
            selectedDirectory = dir;
        }
    }

    void convertFiles() {
        if (selectedDirectory.isEmpty()) {
            QMessageBox::warning(this, "Error", "No directory selected!");
            return;
        }

        // Create output directory
        QDir dir(selectedDirectory);
        QString outputDirName = "converted_csv";
        QString outputDirPath = dir.filePath(outputDirName);

        if (!dir.mkdir(outputDirName)) {
            QMessageBox::warning(this, "Error", "Could not create output directory!");
            return;
        }

        // Find all Excel files
        QStringList excelFiles;
        QStringList filters;
        filters << "*.xls" << "*.xlsx" << "*.xlsm";

        QDirIterator it(selectedDirectory, filters, QDir::Files);
        while (it.hasNext()) {
            excelFiles << it.next();
        }

        if (excelFiles.isEmpty()) {
            QMessageBox::information(this, "No Files Found", "No Excel files found in the selected directory.");
            return;
        }

        // Convert each file
        int successCount = 0;
        int failCount = 0;

        for (const QString &excelFile : excelFiles) {
            QFileInfo fileInfo(excelFile);
            QString baseName = fileInfo.baseName();
            QString csvFileName = outputDirPath + "/" + baseName + ".csv";

            // Use libreoffice in headless mode to convert
            QString program = "libreoffice";
            QStringList arguments;
            arguments << "--headless" << "--convert-to" << "csv" << "--outdir" << outputDirPath << excelFile;

            QProcess process;
            process.start(program, arguments);

            if (!process.waitForFinished(30000)) { // 30 second timeout
                qDebug() << "Conversion failed for" << excelFile;
                failCount++;
            } else {
                successCount++;
            }
        }

        QMessageBox::information(this, "Conversion Complete",
                                QString("Conversion complete!\n\n"
                                        "Successfully converted: %1\n"
                                        "Failed conversions: %2\n\n"
                                        "CSV files saved in: %3")
                                .arg(successCount)
                                .arg(failCount)
                                .arg(outputDirPath));
    }

private:
    void setupUI() {
        QWidget *centralWidget = new QWidget(this);
        QVBoxLayout *layout = new QVBoxLayout(centralWidget);

        QLabel *titleLabel = new QLabel("Excel to CSV Converter", this);
        titleLabel->setStyleSheet("font-size: 18px; font-weight: bold; margin-bottom: 20px;");

        QPushButton *selectButton = new QPushButton("Select Directory", this);
        connect(selectButton, &QPushButton::clicked, this, &ExcelToCsvConverter::selectDirectory);

        directoryLabel = new QLabel("No directory selected", this);
        directoryLabel->setWordWrap(true);

        convertButton = new QPushButton("Convert Excel to CSV", this);
        convertButton->setEnabled(false);
        connect(convertButton, &QPushButton::clicked, this, &ExcelToCsvConverter::convertFiles);

        layout->addWidget(titleLabel);
        layout->addWidget(selectButton);
        layout->addWidget(directoryLabel);
        layout->addWidget(convertButton);

        centralWidget->setLayout(layout);
        setCentralWidget(centralWidget);

        setWindowTitle("Excel to CSV Converter");
        resize(400, 200);
    }

    QLabel *directoryLabel;
    QPushButton *convertButton;
    QString selectedDirectory;
};

int main(int argc, char *argv[]) {
    QApplication app(argc, argv);

    ExcelToCsvConverter converter;
    converter.show();

    return app.exec();
}

#include "main.moc"
```

## Requirements

1. **Qt5 Development Tools**: You need to have Qt5 installed on your system.
2. **LibreOffice**: This program uses LibreOffice in headless mode to perform the conversion. Make sure LibreOffice is installed and available in your system PATH.

## How to Build

1. Save this code to a file named `main.cpp`
2. Create a qmake project file (e.g., `excel2csv.pro`) with the following content:

```qmake
QT += widgets
TARGET = ExcelToCsvConverter
SOURCES += main.cpp
```

3. Build the project using qmake and make:
```bash
qmake excel2csv.pro
make
```

## Alternative Approach

If you don't want to depend on LibreOffice, you could use a library like [QXlsx](https://github.com/QtExcel/QXlsx) to read Excel files directly. Here's how you would modify the conversion part:

```cpp
#include <xlsxdocument.h>

// In the convertFiles() method, replace the conversion loop with:
for (const QString &excelFile : excelFiles) {
    QFileInfo fileInfo(excelFile);
    QString baseName = fileInfo.baseName();
    QString csvFileName = outputDirPath + "/" + baseName + ".csv";

    QXlsx::Document xlsx(excelFile);
    if (xlsx.saveAs(csvFileName)) {
        successCount++;
    } else {
        failCount++;
    }
}
```

You would need to add `QXlsx` to your project file:
```qmake
LIBS += -lQXlsx
```

